{
  "checks": [
    {
      "candidate_id": "pm",
      "verdict": "SUPPORT",
      "reason": "PM 被明确请求组织活动，其角色实体身份有依据；角色名称本身不赋予审批权或其他权限。",
      "sources": [{"quote": "请 PM 组织", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "“请”表达要求，“组织”是明确的主层动作。",
      "sources": [{"quote": "请 PM 组织", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "review",
      "verdict": "SUPPORT",
      "reason": "复核是组织活动的补语内容，具有要求性；这不指定 PM 为复核的实际执行者。",
      "sources": [{"quote": "请 PM 组织依据 SEC-POLICY-12 v3.1 复核 scan-results.json 中的高危发现", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "policy",
      "verdict": "SUPPORT",
      "reason": "规范及版本明确作为复核依据出现，是引用对象，不是受影响材料或独立执行数量。",
      "sources": [{"quote": "依据 SEC-POLICY-12 v3.1 复核", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "scan_file",
      "verdict": "SUPPORT",
      "reason": "文件承载待复核的发现，支持已有输入身份；没有要求生成或修改该文件。",
      "sources": [{"quote": "复核 scan-results.json 中的高危发现", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "findings",
      "verdict": "SUPPORT",
      "reason": "复核对象明确限定为该文件中的高危发现。",
      "sources": [{"quote": "复核 scan-results.json 中的高危发现", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "generate",
      "verdict": "SUPPORT",
      "reason": "明确要求形成产物；将形成动作置于组织的补语内是一种有依据的读法，但其固定 owner 和 layer 存在竞争解释，不能据此消除歧义。",
      "sources": [{"quote": "请 PM 组织依据 SEC-POLICY-12 v3.1 复核 scan-results.json 中的高危发现，并形成 security-audit.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "audit_file",
      "verdict": "SUPPORT",
      "reason": "该文件是形成动作的产物，支持 GENERATED_OUTPUT。",
      "sources": [{"quote": "形成 security-audit.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "exploit",
      "verdict": "SUPPORT",
      "reason": "“不得”明确禁止执行漏洞利用，支持 FORBIDDEN 和否定极性；没有指定具体执行者。",
      "sources": [{"quote": "不得执行漏洞利用", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r1",
      "verdict": "SUPPORT",
      "reason": "PM 是组织动作的明确参与者和执行者，并非仅出现一个职务名称。",
      "sources": [{"quote": "请 PM 组织", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r2",
      "verdict": "CONTRADICT",
      "reason": "来源支持组织与复核的补语关系，但有限合同的 THEME 尾端只允许 ENTITY 或 UNKNOWN_REFERENT；review 是 EVENT，因此此关系编码违反签名。",
      "sources": [{"quote": "组织依据 SEC-POLICY-12 v3.1 复核", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r3",
      "verdict": "CONTRADICT",
      "reason": "generate 是 EVENT，不满足 THEME 尾端签名。此外，将形成动作确定绑定为组织内容，未保留其与组织并列、由 PM 执行的竞争读法。",
      "sources": [{"quote": "请 PM 组织依据 SEC-POLICY-12 v3.1 复核 scan-results.json 中的高危发现，并形成 security-audit.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r4",
      "verdict": "SUPPORT",
      "reason": "“依据”直接将规范绑定为复核依据。",
      "sources": [{"quote": "依据 SEC-POLICY-12 v3.1 复核", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r5",
      "verdict": "SUPPORT",
      "reason": "高危发现是复核直接作用的对象。",
      "sources": [{"quote": "复核 scan-results.json 中的高危发现", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r6",
      "verdict": "SUPPORT",
      "reason": "“中的”支持发现属于该文件内容的关系。",
      "sources": [{"quote": "scan-results.json 中的高危发现", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r7",
      "verdict": "SUPPORT",
      "reason": "形成动作明确以 security-audit.md 为产物。",
      "sources": [{"quote": "形成 security-audit.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r8",
      "verdict": "SUPPORT",
      "reason": "“并”支持复核与形成相连接的读法，但并列层级存在歧义；该观察不能确定两者都由组织支配，也不表示完成条件或严格执行顺序。",
      "sources": [{"quote": "复核 scan-results.json 中的高危发现，并形成 security-audit.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r9",
      "verdict": "SUPPORT",
      "reason": "独立禁令支持任务层面对漏洞利用动作的禁止；TASK 作为合同中的任务锚点，不表示新增执行者或权限。",
      "sources": [{"quote": "不得执行漏洞利用", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    }
  ],
  "findings": [
    {
      "id": "f1",
      "kind": "WRONG_BINDING",
      "candidate_ids": ["r2", "r3"],
      "sources": [{"quote": "组织依据 SEC-POLICY-12 v3.1 复核 scan-results.json 中的高危发现，并形成 security-audit.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
      "reason": "两条 THEME 关系均以 EVENT 为尾端，违反提供的关系签名。语句中的活动补语不能通过此合同下的 THEME 编码；组织与复核的明确活动包含关系可另提 PART_OF 候选。形成的包含关系须先保留作用域歧义。"
    },
    {
      "id": "f2",
      "kind": "AMBIGUITY_COLLAPSED",
      "candidate_ids": ["generate", "r3", "r8"],
      "sources": [{"quote": "请 PM 组织依据 SEC-POLICY-12 v3.1 复核 scan-results.json 中的高危发现，并形成 security-audit.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
      "reason": "“并形成”可以继续组织的补语，也可以与“组织……”在主层并列并共享 PM 主语。图将 generate 固定为 organize 的补语且 unresolved 为空，覆盖理由又无条件认定未指定形成的执行者，消除了这一竞争解释。两种解释都要求形成产物，但动作层级、组织范围及 PM 的参与关系不同。"
    },
    {
      "id": "f3",
      "kind": "COVERAGE_GAP",
      "candidate_ids": ["r2", "r3", "generate", "r8"],
      "sources": [{"quote": "请 PM 组织依据 SEC-POLICY-12 v3.1 复核 scan-results.json 中的高危发现，并形成 security-audit.md。不得执行漏洞利用。", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
      "reason": "c1 包含未保留的形成动作作用域歧义及两条不符合合同的边，不能将整个区域标为已可靠解析的 BOUNDARY_SEMANTIC。"
    }
  ],
  "coverage": [
    {
      "region_id": "c1",
      "disposition": "AMBIGUOUS",
      "candidate_ids": ["pm", "organize", "review", "policy", "scan_file", "findings", "generate", "audit_file", "exploit", "r1", "r2", "r3", "r4", "r5", "r6", "r7", "r8", "r9"],
      "reason": "全区域已检查。组织要求、复核依据与对象、文件内发现、生成产物和利用禁令均有明确来源；形成动作的并列层级和执行者绑定仍有竞争解释，且组织活动的两条 THEME 边违反合同。规范编号和版本没有独立数量约束，来源没有完成条件、审批要求或目的性执行义务。"
    }
  ],
  "additional_candidates": {
    "nodes": [],
    "relations": [
      {
        "id": "a_r1",
        "type": "PART_OF",
        "head": "review",
        "tail": "organize",
        "sources": [{"quote": "组织依据 SEC-POLICY-12 v3.1 复核 scan-results.json 中的高危发现", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
        "ownership": "STRUCTURAL",
        "role": "NONE",
        "alternative_group_id": null
      }
    ],
    "expressions": [],
    "unresolved": [
      {
        "id": "a_u1",
        "kind": "UNRESOLVED_SCOPE",
        "alternatives": [
          "形成与复核同属组织的补语；generate 为 COMPLEMENT，owner 为 organize，形成的实际执行者未明确。",
          "形成与组织在主层并列并共享 PM 主语；generate 为 MAIN，owner 为 TASK，PM 参与形成动作。"
        ],
        "sources": [{"quote": "请 PM 组织依据 SEC-POLICY-12 v3.1 复核 scan-results.json 中的高危发现，并形成 security-audit.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
        "reason": "“并”的并列层级未被来源唯一确定。保留两种解释，不据角色名称或常见工作流程猜测实际执行者，也不静默改写原候选。"
      }
    ]
  }
}
